import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';

// A line item on an invoice: one thing being charged for — a description, how many (qty) and the
// price of each (unitPrice). Everything that shows an invoice's lines shares the key
// ['lineItems', invoiceId]; invalidating it after a write refreshes the list and its total together.
export type LineItem = {
  id: number;
  invoiceId: number;
  description: string;
  qty: number;
  unitPrice: number;
};

export const lineItemsKey = (invoiceId: number) => ['lineItems', invoiceId] as const;

export function useLineItems(invoiceId: number) {
  return useQuery({
    queryKey: lineItemsKey(invoiceId),
    queryFn: () => getJson<LineItem[]>(`/api/lineitems?invoiceId=${invoiceId}`),
  });
}

// Add a line to an invoice: POSTs {invoiceId, description, qty, unitPrice} and returns the saved row.
// Invalidates ['lineItems', invoiceId] so the line list and its total re-read from the server, and
// the ['invoices'] prefix so every invoice list (which shows the worked-out amount) refreshes too —
// the two stay in step by sharing the key, with no import between them.
export function useAddLineItem(invoiceId: number) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: { description: string; qty: number; unitPrice: number }) =>
      postJson<LineItem>('/api/lineitems', { invoiceId, ...input }),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: lineItemsKey(invoiceId) });
      void queryClient.invalidateQueries({ queryKey: ['invoices'] });
    },
  });
}

// Take a line off an invoice: POSTs {id} and returns the updated invoice. Invalidates the same keys
// as adding — ['lineItems', invoiceId] so the line list and its worked-out total re-read, and the
// ['invoices'] prefix so every invoice list showing the amount refreshes too. The total is never
// edited here; it drops because the list re-reads from the server (CLAUDE.md rule 5).
export function useRemoveLineItem(invoiceId: number) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (id: number) => postJson<unknown>('/api/lineitems/remove', { id }),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: lineItemsKey(invoiceId) });
      void queryClient.invalidateQueries({ queryKey: ['invoices'] });
    },
  });
}
import { formatMoney } from '../../ui/money';
import { InvoiceLineItemRow } from '../../slots/defs/invoiceLineItemRow';
import { useLineItems } from './lineItems';

// An invoice's line items and what they add up to. Reads its own query key (scoped to the invoice)
// and derives the invoice amount from the rows — the total is never stored on the client, so it
// always matches the list. Each row shows a description, how many, the price of each, and that
// line's own amount (qty * unit price). The table is always rendered, so an invoice with no lines
// yet still shows the region (and a $0.00 total) ready for the first line to be added.
export function LineItemList({ invoiceId }: { invoiceId: number }) {
  const { data: lineItems } = useLineItems(invoiceId);

  if (!lineItems) {
    return null;
  }

  const total = lineItems.reduce(
    (sum, line) => sum + Number(line.qty) * Number(line.unitPrice),
    0,
  );

  return (
    <table data-testid="invoice-lineitems-table">
      <thead>
        <tr>
          <th>Description</th>
          <th>Qty</th>
          <th>Unit price</th>
          <th>Amount</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        {lineItems.map((line) => (
          <tr key={line.id} data-testid={`lineitem-row-${line.id}`}>
            <td data-testid="lineitem-description">{line.description}</td>
            <td data-testid="lineitem-qty">{line.qty}</td>
            <td data-testid="lineitem-unitprice">{formatMoney(line.unitPrice)}</td>
            <td data-testid="lineitem-amount">
              {formatMoney(Number(line.qty) * Number(line.unitPrice))}
            </td>
            <td>
              <InvoiceLineItemRow.Slot lineItem={line} />
            </td>
          </tr>
        ))}
      </tbody>
      <tfoot>
        <tr>
          <td>Total</td>
          <td></td>
          <td></td>
          <td data-testid="invoice-amount">{formatMoney(total)}</td>
          <td></td>
        </tr>
      </tfoot>
    </table>
  );
}
import { useState } from 'react';
import { useAddLineItem } from './lineItems';

// Add-a-line-item form. useState holds only what the user is currently typing (the description, how
// many, and the price of each) and the validation error for the current attempt. A line needs a
// description, a positive quantity and a positive unit price — otherwise a visible error is shown
// and no row is added (the server + DB enforce the same). On a valid submit it POSTs the line and
// invalidates ['lineItems', invoiceId]; the list and the worked-out total refresh from the server —
// nothing is hand-maintained here.
export function LineItemForm({ invoiceId }: { invoiceId: number }) {
  const [description, setDescription] = useState('');
  const [qty, setQty] = useState('');
  const [unitPrice, setUnitPrice] = useState('');
  const [error, setError] = useState('');
  const add = useAddLineItem(invoiceId);

  return (
    <form
      data-testid="lineitem-form"
      onSubmit={(event) => {
        event.preventDefault();
        const qtyValue = Number(qty);
        const priceValue = Number(unitPrice);
        if (!description.trim()) {
          setError('A description is required');
          return;
        }
        if (!qty.trim() || Number.isNaN(qtyValue) || qtyValue <= 0) {
          setError('Quantity must be more than zero');
          return;
        }
        if (!unitPrice.trim() || Number.isNaN(priceValue) || priceValue <= 0) {
          setError('Unit price must be more than zero');
          return;
        }
        setError('');
        add.mutate(
          { description: description.trim(), qty: qtyValue, unitPrice: priceValue },
          {
            onSuccess: () => {
              setDescription('');
              setQty('');
              setUnitPrice('');
            },
          },
        );
      }}
    >
      <input
        data-testid="lineitem-form-description"
        placeholder="Description"
        value={description}
        onChange={(event) => {
          setDescription(event.target.value);
          setError('');
        }}
      />
      <input
        data-testid="lineitem-form-qty"
        placeholder="Qty"
        value={qty}
        onChange={(event) => {
          setQty(event.target.value);
          setError('');
        }}
      />
      <input
        data-testid="lineitem-form-unitprice"
        placeholder="Unit price"
        value={unitPrice}
        onChange={(event) => {
          setUnitPrice(event.target.value);
          setError('');
        }}
      />
      <button data-testid="lineitem-form-submit" type="submit">
        Add line item
      </button>
      {error && (
        <p data-testid="lineitem-form-error" role="alert">
          {error}
        </p>
      )}
    </form>
  );
}

